/** The left and bottom border, taken from the owner's own tracing.
 *
 *  SOURCE. `floral_frame_revised.svg`, a 700x1000 vector trace of a botanical
 *  ornamental frame, supplied on 2026-11-02 because the hand drawn attempts
 *  before it were not good enough. Nothing here was drawn by this repository:
 *  every number below is the trace's, unchanged.
 *
 *  WHAT WAS TAKEN, AND WHAT WAS LEFT. The trace is a whole portrait frame,
 *  and a sign in screen is landscape, so the rails and the top are dropped.
 *  What is kept is the flowers: the bottom cluster as it stands, and the
 *  right hand group mirrored about the centre line (x becomes 700 - x) so it
 *  climbs the LEFT side instead. That is the border the owner asked for,
 *  bottom and left, and the mirror is what a border like this does anyway.
 *
 *  WHY IT IS BATCHED. The trace is 839 separate outlines. One animated
 *  element each is 839 things repainting; one element for all of them draws
 *  them in a single unbroken sweep with no pauses. These are the middle: the
 *  outlines in drawing order, gathered into runs of roughly equal ink, each
 *  run one path that a dash offset walks along. `len` is that run's ink
 *  length, measured here, so the renderer does not have to ask the browser.
 *
 *  Generated once and committed. There is no build step: if the trace is
 *  ever replaced, this is regenerated and the new numbers are committed too.
 */
export interface Stroke {
  /** One run of outlines, in the order a hand would draw them. */
  d: string;
  /** Its ink length, for the dash array and offset. */
  len: number;
  /** Seconds from the start of the sketch before this run begins. */
  at: number;
  /** Seconds it takes, so every run draws at the same speed. */
  dur: number;
}

